for (const [locale, partial] of Object.entries(lightLocales)) {
  translations[locale] = { ...shared, ...partial };
}

for (const [locale, values] of Object.entries(translations)) {
  const arb = { '@@locale': locale };
  for (const key of Object.keys(shared)) {
    arb[key] = values[key] ?? shared[key];
    if (meta[`@${key}`]) {
      arb[`@${key}`] = meta[`@${key}`];
    }
  }
  fs.writeFileSync(
    path.join(dir, `app_${locale}.arb`),
    `${JSON.stringify(arb, null, 2)}\n`,
  );
}
